import type { Metadata } from "next";
import { CONTACT_EMAIL } from "@/lib/content";
import { SITE_URL } from "@/lib/site";

export const SITE_NAME = "CLIF Foundation";

/**
 * Default share image generated by `app/opengraph-image.tsx`. Next.js only
 * attaches file-based images to segments that do not set their own
 * `openGraph`, so pages reference it explicitly. Keep in sync with that file.
 */
const DEFAULT_SHARE_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "CLIF Foundation — open infrastructure for critical care data",
};

/**
 * Per-page metadata: unique description, self-referencing canonical,
 * Open Graph and Twitter card. `openGraph`/`twitter` objects replace the
 * parent's (shallow merge), so every field is restated here.
 */
export function pageMetadata({
  title,
  description,
  path,
  absoluteTitle = false,
}: {
  title: string;
  description: string;
  /** Route path, e.g. "/" or "/mission". */
  path: string;
  /** Use the title as-is instead of applying the "%s · CLIF Foundation" template. */
  absoluteTitle?: boolean;
}): Metadata {
  const fullTitle = absoluteTitle ? title : `${title} · ${SITE_NAME}`;
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      locale: "en_US",
      siteName: SITE_NAME,
      url: path,
      title: fullTitle,
      description,
      images: [DEFAULT_SHARE_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [DEFAULT_SHARE_IMAGE],
    },
  };
}

/**
 * Organization structured data. Facts only: no tax-exempt status
 * (`nonprofitStatus`) until the IRS determination letter is posted, and no
 * `sameAs` — the Consortium site (clif-icu.com) and the CLIF GitHub
 * organization belong to the CLIF Consortium, not the Foundation. Add
 * `sameAs` only for profiles the Foundation itself owns.
 */
export const ORGANIZATION_JSON_LD = {
  "@context": "https://schema.org",
  "@type": "Organization",
  "@id": `${SITE_URL}/#organization`,
  name: SITE_NAME,
  url: SITE_URL,
  logo: `${SITE_URL}/brand/clif-logo-ink.png`,
  email: CONTACT_EMAIL,
  description:
    "An Illinois nonprofit corporation supporting adoption of the Common Longitudinal ICU data Format (CLIF), an open data standard for critical care electronic health record data.",
  address: {
    "@type": "PostalAddress",
    addressRegion: "IL",
    addressCountry: "US",
  },
  knowsAbout: [
    "Common Longitudinal ICU data Format (CLIF)",
    "Critical care data standards",
    "Electronic health record common data models",
    "Federated critical care research",
  ],
  contactPoint: {
    "@type": "ContactPoint",
    contactType: "general inquiries",
    email: CONTACT_EMAIL,
  },
} as const;

export function jsonLdScript(data: unknown): string {
  return JSON.stringify(data).replace(/</g, "\\u003c");
}
